import heapq

def shortest_path(graph: dict[str, list[tuple[str, float]]], start: str, end: str) -> tuple[float, list[str]]:
    """ 
    Implements Dijkstra's algorithm to find the shortest path in a weighted directed graph.
    Returns the shortest distance and the path as a list of node names.
    """
    # Priority queue for maintaining the nodes to explore
    pq = [(0, start)]
    # Store the shortest distance to each node
    distances = {node: float('inf') for node in graph}
    distances[start] = 0
    # Store the path leading to each node
    previous_nodes = {node: None for node in graph}

    while pq:
        current_distance, current_node = heapq.heappop(pq)

        if current_node == end:
            path = []
            while current_node is not None:
                path.append(current_node)
                current_node = previous_nodes[current_node]
            path.reverse()
            return (current_distance, path)

        if current_distance > distances[current_node]:
            continue

        for neighbor, weight in graph[current_node]:
            distance = current_distance + weight

            if distance < distances[neighbor]:
                distances[neighbor] = distance
                previous_nodes[neighbor] = current_node
                heapq.heappush(pq, (distance, neighbor))

    return (float('inf'), [])

def shortest_path(graph: dict[str, list[tuple[str, float]]], start: str, end: str) -> tuple[float, list[str]]:
    """ 
    Implements the Bellman-Ford algorithm to find the shortest path in a weighted directed graph.
    Returns the shortest distance and the path as a list of node names.
    """
    # Initialize distances and predecessors
    distances = {node: float('inf') for node in graph}
    distances[start] = 0
    predecessors = {node: None for node in graph}

    # Relax edges up to |V| - 1 times
    for _ in range(len(graph) - 1):
        for node in graph:
            for neighbor, weight in graph[node]:
                if distances[node] + weight < distances[neighbor]:
                    distances[neighbor] = distances[node] + weight
                    predecessors[neighbor] = node

    # Check for negative-weight cycles
    for node in graph:
        for neighbor, weight in graph[node]:
            if distances[node] + weight < distances[neighbor]:
                return (float('inf'), [])

    # Reconstruct the shortest path
    if distances[end] == float('inf'):
        return (float('inf'), [])

    path = []
    current_node = end
    while current_node is not None:
        path.append(current_node)
        current_node = predecessors[current_node]

    path.reverse()
    return (distances[end], path)

